const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const agentName = (body.agent_name || '').trim();
  const directive = (body.directive || '').trim();
  const projectId = body.project_id || null; // opcional: null = directiva global del estudio
  const allowedTypes = ['correction','question','instruction','pause'];
  const type = allowedTypes.includes(body.type) ? body.type : 'correction';
  if (!agentName) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'agent_name requerido' } }];
  if (!directive) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'directive requerida' } }];
  if (directive.length > 1500) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'directive demasiado larga (max 1500 chars)' } }];
  const directiveShort = directive.length > 55 ? directive.slice(0, 52) + '...' : directive;
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    agent_name: agentName,
    project_id: projectId,
    directive_text: directive,
    directive_short: directiveShort,
    directive_type: type,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}
